<script lang="ts">
import { onMount } from 'svelte';
import { getFinanceState, loadFinance, loadFinanceSummary, saveCustomerPayment, saveEmployee, saveExpense, saveLabor, savePayment, toggleEmployee } from '../stores/finance.store.svelte';
const state=getFinanceState();
let tab=$state<'expenses'|'labor'|'payments'|'employees'>('expenses'); let selectedChargeId=$state(''); let customerPaymentAmount=$state(''); let customerPaymentDescription=$state('Cobro de cliente'); let customerPaymentReference=$state(''); let reportFrom=$state(new Date(new Date().getFullYear(),new Date().getMonth(),1).toISOString().slice(0,10)); let reportTo=$state(new Date().toISOString().slice(0,10)); let expenseAmount=$state(''); let expenseCategory=$state('operaciones'); let expenseDescription=$state(''); let expenseReference=$state(''); let laborReservation=$state(''); let laborEmployee=$state(''); let laborRole=$state('Instalación'); let laborHours=$state('1'); let laborAmount=$state(''); let laborNotes=$state(''); let paymentEmployee=$state(''); let paymentAmount=$state(''); let paymentDescription=$state('Pago a empleado'); let paymentReference=$state(''); let employeeName=$state(''); let employeeRole=$state('Técnico'); let employeeEmail=$state(''); let employeePhone=$state('');
const accrued=$derived(state.operations.filter(o=>o.operationType==='labor_accrual').reduce((n,o)=>n+Number(o.amount),0)); const expenses=$derived(state.operations.filter(o=>o.operationType==='operating_expense').reduce((n,o)=>n+Number(o.amount),0)); const payments=$derived(state.operations.filter(o=>o.operationType==='employee_payment').reduce((n,o)=>n+Number(o.amount),0)); const openCharges=$derived(state.charges.map(c=>{const paid=state.customerPayments.filter(p=>p.relatedOperationId===c.id).reduce((n,p)=>n+Number(p.amount),0);return {...c,paid,outstanding:Math.max(0,Number(c.amount)-paid)}}).filter(c=>c.outstanding>0.009)); const selectedCharge=$derived(openCharges.find(c=>c.id===selectedChargeId)??null);
async function refresh(){await loadFinance(`${reportFrom}T00:00:00`,`${reportTo}T23:59:59.999`);if(!selectedChargeId||!openCharges.some(c=>c.id===selectedChargeId))selectedChargeId=openCharges[0]?.id??'';if(!laborEmployee&&state.employees.length)laborEmployee=state.employees.find(e=>e.isActive)?.id??'';if(!paymentEmployee&&state.employees.length)paymentEmployee=state.employees[0].id;if(!laborReservation&&state.reservations.length)laborReservation=state.reservations[0].id;}
async function expense(){const amount=Number(expenseAmount);if(!Number.isFinite(amount)||amount<=0||!expenseCategory.trim()||!expenseDescription.trim()){return}await saveExpense(amount,expenseCategory.trim(),expenseDescription.trim(),expenseReference.trim()||null);if(!state.error){expenseAmount='';expenseDescription='';expenseReference='';await refresh()}}
async function labor(){const hours=Number(laborHours),amount=Number(laborAmount);if(!laborReservation||!laborEmployee||!laborRole.trim()||!Number.isFinite(hours)||hours<0||!Number.isFinite(amount)||amount<=0)return;await saveLabor({reservationId:laborReservation,employeeId:laborEmployee,role:laborRole.trim(),hours,amount,notes:laborNotes.trim()});if(!state.error){laborAmount='';laborNotes='';await refresh()}}
async function payment(){const amount=Number(paymentAmount);if(!paymentEmployee||!Number.isFinite(amount)||amount<=0||!paymentDescription.trim())return;await savePayment({employeeId:paymentEmployee,amount,description:paymentDescription.trim(),reference:paymentReference.trim()||null});if(!state.error){paymentAmount='';paymentReference='';await refresh()}}
async function customerPayment(){const amount=Number(customerPaymentAmount);if(!selectedCharge||!Number.isFinite(amount)||amount<=0||amount>selectedCharge.outstanding+.001)return;await saveCustomerPayment({chargeId:selectedCharge.id,amount,description:customerPaymentDescription.trim()||'Cobro de cliente',reference:customerPaymentReference.trim()||null});if(!state.error){customerPaymentAmount='';customerPaymentReference='';await refresh()}}
async function employee(){if(!employeeName.trim())return;await saveEmployee({fullName:employeeName.trim(),roleTitle:employeeRole.trim()||'Técnico',email:employeeEmail.trim()||null,phone:employeePhone.trim()||null});if(!state.error){employeeName='';employeeEmail='';employeePhone='';await refresh()}}
function employeeBalance(id:string){return state.operations.filter(o=>o.employeeId===id&&o.operationType==='labor_accrual').reduce((n,o)=>n+Number(o.amount),0)-state.operations.filter(o=>o.employeeId===id&&o.operationType==='employee_payment').reduce((n,o)=>n+Number(o.amount),0)}
onMount(refresh);
</script>
<svelte:head><title>Finanzas | SOLUX</title></svelte:head>
<div class="page"><header><div><p class="eyebrow">Backoffice / Administración</p><h1>Finanzas y personal</h1><p class="muted">Registro de gastos, obligaciones laborales, pagos y empleados.</p></div><button class="secondary" onclick={refresh} disabled={state.loading}>Actualizar</button></header>{#if state.error}<p class="alert" role="alert">{state.error}</p>{/if}{#if state.notice}<p class="notice" role="status">{state.notice}</p>{/if}
<div class="stats"><article><span>Gastos operativos registrados</span><strong>{expenses.toFixed(2)} USD</strong></article><article><span>Mano de obra acumulada</span><strong>{accrued.toFixed(2)} USD</strong></article><article><span>Pagos a empleados</span><strong>{payments.toFixed(2)} USD</strong></article></div>
<nav class="tabs"><button class:active={tab==='expenses'} onclick={()=>tab='expenses'}>Gastos</button><button class:active={tab==='labor'} onclick={()=>tab='labor'}>Mano de obra</button><button class:active={tab==='payments'} onclick={()=>tab='payments'}>Pagos</button><button class:active={tab==='employees'} onclick={()=>tab='employees'}>Empleados</button></nav>
{#if tab==='expenses'}<section class="panel"><h2>Registrar gasto operativo</h2><div class="form-grid"><label>Importe (USD)<input type="number" min="0.01" step="0.01" bind:value={expenseAmount}/></label><label>Categoría<input bind:value={expenseCategory}/></label><label class="wide">Descripción<input bind:value={expenseDescription}/></label><label>Referencia de factura/recibo<input bind:value={expenseReference}/></label></div><button onclick={expense} disabled={state.saving}>{state.saving?'Guardando…':'Registrar gasto'}</button></section>{:else if tab==='labor'}<section class="panel"><h2>Acumular mano de obra</h2><p class="muted">Registra obligación por trabajo. No significa que dinero haya salido de caja.</p><div class="form-grid"><label>Reserva / trabajo<select bind:value={laborReservation}>{#each state.reservations as r}<option value={r.id}>{r.trackingCode} · {r.customerName} · {r.serviceCategory}</option>{/each}</select></label><label>Empleado<select bind:value={laborEmployee}>{#each state.employees.filter(e=>e.isActive) as e}<option value={e.id}>{e.fullName}</option>{/each}</select></label><label>Función<input bind:value={laborRole}/></label><label>Horas<input type="number" min="0" step="0.25" bind:value={laborHours}/></label><label>Importe acordado (USD)<input type="number" min="0.01" step="0.01" bind:value={laborAmount}/></label><label>Notas<input bind:value={laborNotes}/></label></div><button onclick={labor} disabled={state.saving||!state.reservations.length||!state.employees.some(e=>e.isActive)}>{state.saving?'Guardando…':'Registrar obligación'}</button></section>{:else if tab==='payments'}<section class="panel"><h2>Registrar pago a empleado</h2><p class="muted">Pago limitado al saldo laboral acumulado pendiente.</p><div class="form-grid"><label>Empleado<select bind:value={paymentEmployee}>{#each state.employees as e}<option value={e.id}>{e.fullName}{e.isActive?'':' (inactivo)'}</option>{/each}</select></label><label>Importe (USD)<input type="number" min="0.01" step="0.01" bind:value={paymentAmount}/></label><label>Descripción<input bind:value={paymentDescription}/></label><label>Referencia bancaria/recibo<input bind:value={paymentReference}/></label></div>{#if paymentEmployee}<p class="balance">Saldo calculado: {employeeBalance(paymentEmployee).toFixed(2)} USD</p>{/if}<button onclick={payment} disabled={state.saving||!paymentEmployee}>{state.saving?'Procesando…':'Registrar pago'}</button></section>{:else}<section class="panel"><h2>Nuevo empleado</h2><div class="form-grid"><label>Nombre completo<input bind:value={employeeName}/></label><label>Cargo<input bind:value={employeeRole}/></label><label>Email<input type="email" bind:value={employeeEmail}/></label><label>Teléfono<input bind:value={employeePhone}/></label></div><button onclick={employee} disabled={state.saving}>{state.saving?'Guardando…':'Crear empleado'}</button><h2 class="subheading">Personal registrado</h2><div class="table-wrap"><table><thead><tr><th>Empleado</th><th>Cargo</th><th>Estado</th><th>Saldo laboral</th><th></th></tr></thead><tbody>{#each state.employees as e}<tr><td>{e.fullName}<small>{e.email??e.phone??''}</small></td><td>{e.roleTitle}</td><td>{e.isActive?'Activo':'Inactivo'}</td><td>{employeeBalance(e.id).toFixed(2)} USD</td><td><button class="secondary compact" onclick={()=>toggleEmployee(e)} disabled={state.saving}>{e.isActive?'Desactivar':'Activar'}</button></td></tr>{/each}</tbody></table></div></section>{/if}
<section class="panel"><h2>Cobros de clientes</h2><p class="muted">Cada cobro se vincula a cargo y no puede superar saldo pendiente.</p><div class="form-grid"><label class="wide">Cargo pendiente<select bind:value={selectedChargeId}>{#each openCharges as charge}<option value={charge.id}>{new Date(charge.occurredAt).toLocaleDateString()} · {charge.description} · Pendiente {charge.outstanding.toFixed(2)} {charge.currency}</option>{/each}</select></label>{#if selectedCharge}<p class="balance wide">Cargo: {Number(selectedCharge.amount).toFixed(2)} {selectedCharge.currency}. Pagado: {selectedCharge.paid.toFixed(2)}. Pendiente: {selectedCharge.outstanding.toFixed(2)}.</p>{/if}<label>Importe recibido (USD)<input type="number" min="0.01" max={selectedCharge?.outstanding??undefined} step="0.01" bind:value={customerPaymentAmount}/></label><label>Descripción<input bind:value={customerPaymentDescription}/></label><label class="wide">Referencia de transferencia/recibo<input bind:value={customerPaymentReference}/></label></div>{#if !openCharges.length}<p class="muted">No hay cargos pendientes.</p>{/if}<button onclick={customerPayment} disabled={state.saving||!selectedCharge}>{state.saving?'Registrando…':'Registrar cobro recibido'}</button></section>
<section class="panel"><h2>Informe financiero</h2><p class="muted">Flujo estimado excluye compras de inventario y pagos a proveedores.</p><div class="report-controls"><label>Desde<input type="date" bind:value={reportFrom}/></label><label>Hasta<input type="date" bind:value={reportTo}/></label><button class="secondary" onclick={()=>loadFinanceSummary(`${reportFrom}T00:00:00`,`${reportTo}T23:59:59.999`)} disabled={state.reportLoading||!reportFrom||!reportTo||reportFrom>reportTo}>{state.reportLoading?'Consultando…':'Consultar periodo'}</button></div>{#if state.summary}<div class="report-grid"><article><span>Ventas brutas</span><strong>{Number(state.summary.salesGross).toFixed(2)} USD</strong></article><article><span>Comisión ventas gestionadas</span><strong>{Number(state.summary.managedSalesCommission).toFixed(2)} USD</strong></article><article><span>Cobros de clientes</span><strong>{Number(state.summary.customerCashIn).toFixed(2)} USD</strong></article><article><span>Reembolsos</span><strong>{Number(state.summary.customerRefunds).toFixed(2)} USD</strong></article><article><span>Gastos operativos</span><strong>{Number(state.summary.operatingExpenses).toFixed(2)} USD</strong></article><article><span>Compras inventario</span><strong>{Number(state.summary.inventoryPurchases).toFixed(2)} USD</strong></article><article><span>Mano de obra acumulada</span><strong>{Number(state.summary.laborAccrued).toFixed(2)} USD</strong></article><article><span>Pagos empleados</span><strong>{Number(state.summary.employeeCashOut).toFixed(2)} USD</strong></article><article><span>Flujo caja estimado</span><strong>{Number(state.summary.estimatedCashFlow).toFixed(2)} USD</strong></article><article><span>Cargos pendientes</span><strong>{Number(state.summary.unpaidCustomerCharges).toFixed(2)} USD</strong></article></div>{/if}</section>
<section class="panel"><h2>Libro financiero reciente</h2>{#if state.loading}<p>Cargando…</p>{:else if !state.operations.length}<p class="muted">Sin operaciones.</p>{:else}<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Descripción</th><th>Estado</th><th>Importe</th></tr></thead><tbody>{#each state.operations as op}<tr><td>{new Date(op.occurredAt).toLocaleDateString()}</td><td>{op.operationType}</td><td>{op.description}<small>{op.category}</small></td><td>{op.status}</td><td>{Number(op.amount).toFixed(2)} {op.currency}</td></tr>{/each}</tbody></table></div>{/if}</section></div>
<style>.page{padding:clamp(20px,4vw,40px);max-width:1250px;margin:0 auto;color:var(--color-text)}header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}h1{font-size:clamp(26px,3vw,36px);margin:4px 0 8px}h2{font-size:18px;margin:0 0 18px}.subheading{margin-top:28px}.eyebrow{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--color-primary);font-weight:800;margin:0}.muted,small{color:var(--color-muted);font-size:13px;line-height:1.5}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:16px}.stats article{padding:16px;border:1px solid var(--color-border);border-radius:12px;display:flex;flex-direction:column;gap:8px}.stats span{font-size:12px;color:var(--color-muted)}.stats strong{font-size:22px}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.tabs button{background:var(--color-surface-2);color:var(--color-text);border:1px solid var(--color-border)}.tabs button.active{background:var(--color-primary);color:white}.panel{background:var(--color-surface);border:1px solid var(--color-border);border-radius:14px;padding:22px;margin-bottom:16px}label{display:flex;flex-direction:column;gap:7px;font-size:13px;font-weight:650}input,select{width:100%;min-width:0;padding:10px 12px;border:1px solid var(--color-border);border-radius:8px;background:var(--color-background);color:var(--color-text)}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:18px 0}.wide{grid-column:1/-1}.report-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr)) auto;gap:12px;align-items:end;margin:18px 0}.report-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:18px}.report-grid article{padding:14px;border:1px solid var(--color-border);border-radius:10px;display:flex;flex-direction:column;gap:8px}.report-grid span{font-size:12px;color:var(--color-muted)}.report-grid strong{font-size:18px}button{border:0;border-radius:8px;padding:11px 16px;background:var(--color-primary);color:white;font-weight:750;cursor:pointer}button:disabled{opacity:.55;cursor:not-allowed}.secondary{background:var(--color-surface-2);color:var(--color-text);border:1px solid var(--color-border)}.compact{padding:7px 10px;font-size:12px}.alert,.notice{padding:12px 14px;border-radius:8px;margin:0 0 16px;font-size:13px}.alert{background:#fee2e2;color:#991b1b}.notice{background:#dcfce7;color:#166534}.balance{font-size:13px;font-weight:700}.table-wrap{overflow:auto;margin-top:14px}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:11px;border-bottom:1px solid var(--color-border);font-size:13px}td small{display:block}@media(max-width:680px){header{align-items:flex-start;flex-direction:column}.stats,.report-grid{grid-template-columns:1fr}.form-grid,.report-controls{grid-template-columns:1fr}.wide{grid-column:auto}}</style>
